# Define Retention Ratios
# R1 = AMC12 / MATH-500
# R2 = AIME-2024 / AMC12

colors = {
    'baseline': '#94A3B8',
    'sft': '#3B82F6',
    'grpo': '#F59E0B',
    'grpo_without_std_norm': '#E11D48',
    'drgrpo': '#8B5CF6',
    'instruct': '#0F172A'
}

plt.figure(figsize=(14, 8))

# Subplot 1: R1 (AMC12 / MATH-500)
plt.subplot(1, 2, 1)
for m in models:
    acc_math = np.array(math500[m])[k_indices]
    acc_amc = np.array(amc12[m])[k_indices]
    r1 = acc_amc / acc_math
    plt.plot(k_values, r1, marker='o', label=m, color=colors[m], linewidth=2)
plt.xscale('log')
plt.xticks(k_values, [str(k) for k in k_values])
plt.xlabel('Sampling Attempts (k)')
plt.ylabel('Retention Ratio (AMC12 / MATH-500)')
plt.title('Easy-to-Mid Difficulty Retention')
plt.grid(True, linestyle=':', alpha=0.6)
plt.legend(fontsize=9)

# Subplot 2: R2 (AIME-2024 / AMC12)
plt.subplot(1, 2, 2)
for m in models:
    acc_amc = np.array(amc12[m])[k_indices]
    acc_aime = np.array(aime24[m])[k_indices]
    # Handle division by zero
    r2 = []
    for a, b in zip(acc_amc, acc_aime):
        if a == 0:
            r2.append(0)
        else:
            r2.append(b / a)
    plt.plot(k_values, r2, marker='s', label=m, color=colors[m], linewidth=2)
plt.xscale('log')
plt.xticks(k_values, [str(k) for k in k_values])
plt.xlabel('Sampling Attempts (k)')
plt.ylabel('Retention Ratio (AIME-24 / AMC12)')
plt.title('Mid-to-Hard Difficulty Retention')
plt.grid(True, linestyle=':', alpha=0.6)
plt.legend(fontsize=9)

plt.suptitle('Multi-Difficulty Reasoning Retention Curves', fontsize=16, fontweight='bold')
plt.tight_layout(rect=[0, 0.03, 1, 0.95])
plt.savefig('asset/multi_difficulty_retention.png', dpi=300)
plt.close()

# Print metrics for thought trace
for m in models:
    acc_math = np.array(math500[m])[k_indices]
    acc_amc = np.array(amc12[m])[k_indices]
    acc_aime = np.array(aime24[m])[k_indices]
    r1_p1 = acc_amc[0] / acc_math[0]
    r1_p64 = acc_amc[-1] / acc_math[-1]
    r2_p1 = acc_aime[0] / acc_amc[0] if acc_amc[0] > 0 else 0
    r2_p64 = acc_aime[-1] / acc_amc[-1] if acc_amc[-1] > 0 else 0
    print(f"{m}: R1(p1)={r1_p1:.2f}, R1(p64)={r1_p64:.2f} | R2(p1)={r2_p1:.2f}, R2(p64)={r2_p64:.2f}")